package com.bank.invest.service;

import com.bank.invest.model.Project;
import java.math.BigDecimal;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Greedily selects up to K affordable projects to maximize final capital.
public class CapitalMaximizer {
    private static final Logger log = Logger.getLogger(CapitalMaximizer.class.getName());

    public BigDecimal maximizeCapital(BigDecimal initial, int k, List<Project> projects) {
        // Min-heap by required capital: cheapest-to-enter first.
        PriorityQueue<Project> minCapital =
                new PriorityQueue<>(Comparator.comparing(Project::getRequired));
        minCapital.addAll(projects);
        // Max-heap by profit: most profitable affordable project on top.
        PriorityQueue<Project> maxProfit =
                new PriorityQueue<>(Comparator.comparing(Project::getProfit).reversed());

        BigDecimal capital = initial;
        for (int round = 0; round < k; round++) {
            // Unlock everything we can now afford.
            while (!minCapital.isEmpty()
                    && minCapital.peek().getRequired().compareTo(capital) <= 0) {
                maxProfit.offer(minCapital.poll());
            }
            if (maxProfit.isEmpty()) {
                log.info("No affordable project left; stopping early");
                break;
            }
            Project chosen = maxProfit.poll();
            capital = capital.add(chosen.getProfit());
            BigDecimal snapshot = capital;
            log.info(() -> "Picked " + chosen.getName()
                    + " profit=" + chosen.getProfit() + " capital=" + snapshot);
        }
        BigDecimal finalCapital = capital;
        log.info(() -> "Final capital = " + finalCapital);
        return capital;
    }
}
