package com.bank.invest;

import com.bank.invest.model.Project;
import com.bank.invest.service.CapitalMaximizer;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class CapitalApplication {
    private static final Logger log = Logger.getLogger(CapitalApplication.class.getName());

    public static void main(String[] args) {
        List<Project> deals = List.of(
                new Project("DealA", new BigDecimal("0"),    new BigDecimal("100000")),
                new Project("DealB", new BigDecimal("100000"), new BigDecimal("200000")),
                new Project("DealC", new BigDecimal("200000"), new BigDecimal("300000")));
        CapitalMaximizer maximizer = new CapitalMaximizer();
        BigDecimal result = maximizer.maximizeCapital(new BigDecimal("0"), 2, deals);
        log.info("NBI investment desk final capital: " + result);
    }
}
